package io.github.turbopro.ism.operation.task;import io.github.turbopro.ism.common.api.ApiResponse;import io.github.turbopro.ism.common.infrastructure.authorization.RequiresPermission;import io.github.turbopro.ism.common.infrastructure.web.ApiResponseFactory;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/tasks")public class TaskCenterController{private final TaskCenterService service;private final ApiResponseFactory responses;public TaskCenterController(TaskCenterService service,ApiResponseFactory responses){this.service=service;this.responses=responses;}@GetMapping @RequiresPermission("task:center:view")ApiResponse<List<TaskCenterModels.TaskView>>tasks(){return responses.success(service.tasks());}@GetMapping("/{id}")@RequiresPermission("task:center:view")ApiResponse<TaskCenterModels.TaskView>task(@PathVariable long id){return responses.success(service.task(id));}@PostMapping("/{id}/cancel")@RequiresPermission("task:center:operate")ApiResponse<TaskCenterModels.TaskView>cancel(@PathVariable long id,@RequestBody TaskCenterModels.VersionCommand c){return responses.success(service.cancel(id,c.version()));}@PostMapping("/{id}/retry")@RequiresPermission("task:center:operate")ApiResponse<TaskCenterModels.TaskView>retry(@PathVariable long id,@RequestBody TaskCenterModels.VersionCommand c){return responses.success(service.retry(id,c.version()));}}
